class Solution {
public:
    int minimumTime(int n, vector<vector<int>>& relations, vector<int>& time) {
        vector<vector<int>> adj(n + 1);
        vector<int> indegree(n + 1, 0);
        for (auto& r : relations) {
            adj[r[0]].push_back(r[1]);
            indegree[r[1]]++;
        }
        vector<long long> completion(n + 1, 0);
        for (int i = 1; i <= n; i++) completion[i] = time[i - 1];

        queue<int> q;
        for (int i = 1; i <= n; i++) {
            if (indegree[i] == 0) q.push(i);
        }

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                completion[v] = max(completion[v], completion[u] + time[v - 1]);
                if (--indegree[v] == 0) q.push(v);
            }
        }

        long long ans = 0;
        for (int i = 1; i <= n; i++) ans = max(ans, completion[i]);
        return (int)ans;
    }
};
